package com.oms.goods;
import com.oms.goods.service.goods.impl.GoodsLuckyBagService;
import org.junit.jupiter.api.*;
import java.util.*;
import static com.oms.common.lucky.LuckyBagRules.*;
import static org.junit.jupiter.api.Assertions.*;

class GoodsLuckyBagTest {
    GoodsWorkspaceTest f;GoodsLuckyBagService service;long bag;
    @BeforeAll static void start(){GoodsWorkspaceTest.init();}
    @AfterAll static void stop(){GoodsWorkspaceTest.close();}
    @BeforeEach void setup(){f=new GoodsWorkspaceTest();f.seed();service=f.context.getBean(GoodsLuckyBagService.class);f.goods.saveGoods("QM",f.product("A"),"test");f.goods.saveGoods("QM",f.product("B"),"test");Map<String,Object> g=f.product("FD");g.put("isFd",1);bag=f.goods.saveGoods("QM",g,"test");}
    Map<String,Object> input(){return map("revision",0,"draft_revision",0,"enabled",1,"mode","RANDOM","selection","WEIGHTED","groups",Arrays.asList(map("key","g1","name","上装","candidates",Arrays.asList(map("sku_sn","A","weight",1),map("sku_sn","B","weight",2)))));}
    @Test void draftsDoNotReplacePublishedRulesAndBothVersionsAreFenced(){Map<String,Object> first=input();service.save("QM",bag,first,"test",true);assertThrows(IllegalArgumentException.class,()->service.save("QM",bag,first,"stale",true));Map<String,Object> next=input();next.put("revision",1);next.put("draft_revision",1);next.put("enabled",0);Map<String,Object> r=service.save("QM",bag,next,"test",false);assertEquals(1,number(object(r.get("published")),"enabled"));assertEquals(0,number(object(r.get("draft")),"enabled"));assertEquals(1,f.db.queryForObject("SELECT COUNT(*) FROM goods_lucky_bag_version",Integer.class));}
    @SuppressWarnings("unchecked") Map<String,Object> object(Object value){return (Map<String,Object>)value;}
    @Test void crossCompanyAndNestedOrMissingComponentsAreRejected(){assertThrows(IllegalArgumentException.class,()->service.detail("OTHER",bag));Map<String,Object> i=input();i.put("groups",Arrays.asList(map("key","g1","name","g1","candidates",Arrays.asList(map("sku_sn","FD","weight",1)))));assertThrows(IllegalArgumentException.class,()->service.save("QM",bag,i,"test",true));i.put("groups",Arrays.asList(map("key","g1","name","g1","candidates",Arrays.asList(map("sku_sn","MISSING","weight",1)))));assertThrows(IllegalArgumentException.class,()->service.save("QM",bag,i,"test",true));}
    @Test void publishedParentAndCandidateIdentitiesCannotBeDestroyed(){service.save("QM",bag,input(),"test",true);long a=f.db.queryForObject("SELECT id FROM goods_sku_sn_info WHERE sku_sn='A'",Long.class);Map<String,Object> change=f.product("A");change.put("id",a);change.put("isFd",1);assertThrows(IllegalArgumentException.class,()->f.goods.saveGoods("QM",change,"test"));assertThrows(IllegalArgumentException.class,()->f.goods.deleteGoods("QM",Collections.singletonList(a)));Map<String,Object> normal=f.product("FD");normal.put("id",bag);assertThrows(IllegalArgumentException.class,()->f.goods.saveGoods("QM",normal,"test"));}
    @Test void catalogPublishesOnlyTheImmutableVersion(){service.save("QM",bag,input(),"test",true);List<Map<String,Object>> rows=new ArrayList<>();rows.add(map("sku_sn","FD","is_fd",1));rows.add(map("sku_sn","A","is_fd",0));service.attach("QM",rows);assertEquals(1,number(object(rows.get(0).get("lucky_bag")),"revision"));assertFalse(rows.get(1).containsKey("lucky_bag"));}
    @Test void oldPublishedComponentsKeepPhysicalIdentityAfterAReplacementRule(){service.save("QM",bag,input(),"test",true);Map<String,Object> next=input();next.put("revision",1);next.put("draft_revision",1);next.put("groups",Arrays.asList(map("key","g1","name","Only B","candidates",Arrays.asList(map("sku_sn","B","weight",1)))));service.save("QM",bag,next,"test",true);long a=f.db.queryForObject("SELECT id FROM goods_sku_sn_info WHERE sku_sn='A'",Long.class);Map<String,Object> changed=f.product("A");changed.put("id",a);changed.put("isFd",1);assertThrows(IllegalArgumentException.class,()->f.goods.saveGoods("QM",changed,"test"));assertEquals(2,f.db.queryForObject("SELECT COUNT(*) FROM goods_lucky_bag_component",Integer.class));}
    @Test void incompleteDraftCanBeSavedButCannotBePublished(){Map<String,Object> i=input();i.put("groups",Collections.emptyList());Map<String,Object> saved=service.save("QM",bag,i,"test",false);assertEquals(0,number(saved,"revision"));assertEquals(1,number(saved,"draft_revision"));i.put("draft_revision",1);assertThrows(IllegalArgumentException.class,()->service.save("QM",bag,i,"test",true));}
}
